package com.bank.ctemat.plan;

public class CteNode {
    private final boolean materialized;   // true = fence, false = inlined
    private final int references;          // how many times used in the statement

    public CteNode(boolean materialized, int references) {
            this.materialized = materialized;
            this.references = references;
    }
    public boolean isMaterialized() { return materialized; }
    public int getReferences() { return references; }
}
