package com.bank.ctemat.plan;

import java.util.logging.*;

// Estimates cost: materialized ignores outer filter; inlined pushes it down.
public class CtePlanner {
    private static final Logger log = Logger.getLogger(CtePlanner.class.getName());
    private final long tableRows;
    private final long rowsForOneAccount;

    public CtePlanner(long tableRows, long rowsForOneAccount) {
            this.tableRows = tableRows;
            this.rowsForOneAccount = rowsForOneAccount;
    }

    public long cost(CteNode node) {
        long cost;
        if (node.isMaterialized()) {
            // compute CTE over whole table ONCE, reuse across references; filter CANNOT push down
            cost = tableRows + (long) node.getReferences() * rowsForOneAccount;
        } else {
            // inlined: outer filter pushes into base scan, recomputed per reference
            cost = (long) node.getReferences() * rowsForOneAccount;
        }
        final long c = cost;
        log.info(() -> (node.isMaterialized() ? "MATERIALIZED" : "INLINED")
                + " refs=" + node.getReferences() + " → cost=" + c);
        return cost;
    }
}
