package com.bank.ctemat;

import com.bank.ctemat.plan.*;
import java.util.logging.*;

public class CteMatDemo {
    private static final Logger log = Logger.getLogger(CteMatDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        CtePlanner planner = new CtePlanner(200_000_000L, 500L);

        log.info("=== Single-use CTE, outer filters to one account ===");
        long fenced  = planner.cost(new CteNode(true, 1));    // old PG: fence, scans all
        long inlined = planner.cost(new CteNode(false, 1));   // PG12+: filter pushes down
        log.info(() -> "Single-use: inlined is " + (fenced / Math.max(inlined,1)) + "x cheaper");

        log.info("=== CTE referenced 3 times (expensive base) ===");
        long matReuse = planner.cost(new CteNode(true, 3));   // compute once, reuse 3x
        long inReuse  = planner.cost(new CteNode(false, 3));  // inlined → recompute 3x
        log.info(() -> "Multi-ref with cheap filter: inlined=" + inReuse + " vs materialized=" + matReuse);
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

